  // command we can just pass it directly to the shell.
  return {
    method: 'single-quote',
    script: command,
    invocation: `bash -c ${quoted}`,
    note: cwd ? `运行前先 cd 到 ${cwd}` : '无 cwd 切换,使用当前目录'
